import{c as t,Q as o,j as a,m as n}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Anthropic just dropped 5 workshops, revealing the latest capabilities of Fable 5","description":"","frontmatter":{"url":"https://x.com/0xcodez/status/2073478036154966486","title":"Anthropic just dropped 5 workshops, revealing the latest capabilities of Fable 5","archived":"2026-07-06T00:00:00.000Z","duration":"84:55","handle":"@0xCodez","published":"2026-07-04T00:00:00.000Z","subtitle_lang":"en","type":"video"},"headers":[],"relativePath":"research/tweets/2026-07-04-@0xCodez-2073478036154966486.md","filePath":"research/tweets/2026-07-04-@0xCodez-2073478036154966486.md","lastUpdated":1785909234000}'),s={name:"research/tweets/2026-07-04-@0xCodez-2073478036154966486.md"};function i(r,e,l,h,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="anthropic-just-dropped-5-workshops-revealing-the-latest-capabilities-of-fable-5-—-0xcodez" tabindex="-1">Anthropic just dropped 5 workshops, revealing the latest capabilities of Fable 5 — @0xCodez <a class="header-anchor" href="#anthropic-just-dropped-5-workshops-revealing-the-latest-capabilities-of-fable-5-—-0xcodez" aria-label="Permalink to &quot;Anthropic just dropped 5 workshops, revealing the latest capabilities of Fable 5 — @0xCodez&quot;">​</a></h1><p><strong>來源</strong>: <a href="https://x.com/0xcodez/status/2073478036154966486" target="_blank" rel="noreferrer">https://x.com/0xcodez/status/2073478036154966486</a><strong>發布日期</strong>: 2026-07-04 <strong>收錄日期</strong>: 2026-07-06 <strong>時長</strong>: 84:55</p><blockquote><p>Anthropic 在東京 Code with Claude 大會同日發布 Claude Fable 5 與 Mythos 5，5 場工作坊完整呈現能力、基礎設施與部署策略。</p></blockquote><hr><h2 id="整理版-可讀逐字稿" tabindex="-1">整理版（可讀逐字稿） <a class="header-anchor" href="#整理版-可讀逐字稿" aria-label="Permalink to &quot;整理版（可讀逐字稿）&quot;">​</a></h2><h3 id="workshop-1-—-fable-5-能力總覽-00-00–11-22-diane" tabindex="-1">Workshop 1 — Fable 5 能力總覽（00:00–11:22，Diane） <a class="header-anchor" href="#workshop-1-—-fable-5-能力總覽-00-00–11-22-diane" aria-label="Permalink to &quot;Workshop 1 — Fable 5 能力總覽（00:00–11:22，Diane）&quot;">​</a></h3><p>大家好，早安東京。我是 Diane，2023 年加入 Anthropic，參與了從 Claude 2 起算的每個版本——共 21 個版本，涵蓋 Haiku、Sonnet、Opus，以及現在的 Fable 和 Mythos。</p><p>我們最新的發布就在幾小時前完成。我們推出了 Claude Fable 5 和 Claude Mythos 5，這是第五代模型的第一批。Fable 5 是我們有史以來最強的可公開使用模型，和 Mythos 5 基於相同底層架構。這些模型已在 Anthropic 內部加速我們的工作。</p><p>Anthropic 談論很多指數級增長——但這到底意味著什麼？隨著模型智能提升，它能創造的應用價值呈指數增長。今天許多人使用的 agentic coding 比幾年前的自動補全有價值得多。Fable 5 就是這種趨勢的具體體現。</p><p><strong>Fable 5 的關鍵優勢——兩個驅動差距的因素</strong>：</p><p><em>第一，單次正確率</em>：給 Fable 5 一個複雜、描述清晰的問題，它能一次通過。早期測試者反映，單個 prompt 可以完成原本需要一個團隊花幾天甚至幾週的工作。</p><p><em>第二，長程自主性</em>：Fable 5 能在單一目標下運行數天，全程保持連貫，即使任務跨越數百萬 token，也能記住你的規格說明。它調度 sub-agent 的能力更可靠，且更具成本意識。</p><p>Fable 5 不只擅長寫程式碼，它在讀程式碼方面甚至更出色：更擅長排查故障、挖掘 repo 歷史找出問題所在，並主動提出改善建議。在 coding 之外，它也適用於組織實際運轉的工作——財務分析、文件、簡報、試算表——端到端處理，以專業水準回傳成果。</p><p><strong>安全機制</strong>：Glasswing 計畫始於兩個月前，當時 Mythos Preview 的網路安全能力強到可能被濫用，因此只開放少數合作夥伴。之後我們建立了新的安全保護系統：當請求觸及網路安全、生物或化學主題時，Fable 會路由到 Opus 4.8 處理，回應明確標注，計費按 Opus 定價。這讓最強模型能在今天（而非幾個月後）交到所有人手中。</p><p>早期客戶反饋：Rakuten 表示最高 effort 下 Fable 5 能驗證自己的工作，讓自主自動化操作成為可能；Cognition 在其 Frontier Bench 上 Fable 5 得分最高，強調長程推理和對陌生工具的泛化能力；Jen Spark 表示 Fable 5 在所有測試模型中排名第一，在 UI 設計和遊戲 coding 等最難任務上表現尤為突出。</p><p>Mythos 5（解除網路安全/生物安全限制的版本）今日開放給 Glasswing 合作夥伴；本月稍後將向生命科學研究者開放，因為讓生物技術風險的同一種能力，正是 AI 在這個領域產生最大正向影響的能力。</p><p><strong>開發建議</strong>：</p><ol><li>為下一版 Claude 設計，而非當前版本——勝出的開發者架構、harness 和產品體驗能夠吸收下一輪智能跳躍。</li><li>建立更難的 evals 和產品原型，測試目前尚不可行的體驗。當某個任務開始奏效，那是出貨魔法產品的訊號。</li><li>讓 model 升級變得簡單：自動化 eval、測試流程，將 model 升級視為商業機會。</li></ol><hr><h3 id="workshop-2-—-能力曲線-11-22–30-54-theo" tabindex="-1">Workshop 2 — 能力曲線（11:22–30:54，Theo） <a class="header-anchor" href="#workshop-2-—-能力曲線-11-22–30-54-theo" aria-label="Permalink to &quot;Workshop 2 — 能力曲線（11:22–30:54，Theo）&quot;">​</a></h3><p>我是 Theo，負責長程能力（長上下文和記憶）。大約兩年前加入，那時 Sonnet 3.5 剛剛發布，agents 幾乎還不是個詞，模型能做 coding 只是生命跡象。去年此時 Opus 4 剛發布，Claude Code 還未 GA。現在我們有了 Fable、Mythos 和 Opus 4.8。</p><p><strong>指標觀察</strong>：在場超過半數的人認為 Claude 讓他們效率提升 10 倍。Anthropic 內部超過 80% 的程式碼由 Claude 合並。</p><p><strong>SWE-bench 能力曲線</strong>：</p><table tabindex="0"><thead><tr><th>模型</th><th>SWE-bench Verified</th><th>備注</th></tr></thead><tbody><tr><td>Sonnet 3.7</td><td>62%</td><td>12 個月前</td></tr><tr><td>Opus 4.8</td><td>88%</td><td>現在</td></tr><tr><td>Fable/Mythos</td><td>飽和</td><td>benchmark 已不夠難</td></tr></tbody></table><p>從 62% 到 88% 意味著舊模型的失敗率是新模型的 3 倍。demo 中 Sonnet 4 重建 Claude.ai 網站時直接行動、不規劃，結果無法完全運作；Opus 4.8 先規劃再執行，最終用更少 tool 呼叫、更少行程式碼完成，且結果完全正確。</p><p><strong>三大智能躍升</strong>：</p><p><em>1. 先規劃後執行</em>：舊模型像沒看說明書就組裝 IKEA 家具，直接衝進去然後失敗。新模型先思考規格再執行，途中自我修正（說「actually」或「never mind」），首次執行就更高效。開發建議：允許模型先思考，在 UX 中給予 adaptive thinking 空間，使用 effort dial。</p><p><em>2. 錯誤恢復與自我修正</em>：舊模型遇到反饋後一遍遍重複相同的失敗方案，即 &quot;doom looping&quot;。新模型真正看反饋並嘗試不同方法，往往帶來更好結果，且廢棄 token 更少。開發建議：設計能給模型反饋的環境（tool 或人類回饋）。</p><p><em>3. 長程連貫性</em>：舊模型中途忘記任務、丟失規格，即「losing the plot」。現在模型能維持到百萬 token 的連貫性。開發建議：可以放手給整個 codebase 而非單一檔案，無需再大量切分上下文。</p><p>客戶驗證：Shopify 認為 Opus 4.8 錯誤恢復和規劃明顯改善；Cursor 發現工具呼叫和 token 效率大幅提升；Cognition 表示 Opus 4.8 更自主、能運行更長時間、更省 token。</p><p><strong>戰術建議（如何為不斷進化的模型開發）</strong>：</p><p>心態轉變：要有野心，測試 Claude 今天做不到的事，而非只測 12 個月前能做的事。</p><ol><li><p><strong>建立/更新 evals</strong>：eval 是 AI 時代的單元測試；創建今天模型尚未飽和的測試案例；如果 eval 不動了，表示它可能已飽和，是時候更新了。</p></li><li><p><strong>縮短 scaffolding</strong>：提示寫的是意圖，而非針對舊模型所有失敗的 workaround。系統提示中的過時指令可能讓新模型錯誤遵循。精簡 scaffolding，讓模型展示它能做什麼。</p></li><li><p><strong>給模型空間</strong>：使用 adaptive thinking 和 effort dial；讓 agent 有更多 environment 訪問權限（用 classifier 控制，如 auto mode in Claude Code）；閉合 agent loop——給模型驗證輸出的手段（如 computer use tool 做 QA）。</p></li></ol><hr><h3 id="workshop-3-—-claude-managed-agents-30-54–44-29-jess-michael" tabindex="-1">Workshop 3 — Claude Managed Agents（30:54–44:29，Jess + Michael） <a class="header-anchor" href="#workshop-3-—-claude-managed-agents-30-54–44-29-jess-michael" aria-label="Permalink to &quot;Workshop 3 — Claude Managed Agents（30:54–44:29，Jess + Michael）&quot;">​</a></h3><p><strong>背景</strong>：隨著模型能力指數級增長，瓶頸越來越是基礎設施而非智能本身。</p><p>能力演進時間線：</p><ul><li>2 年前（Opus 3）：寫並測試單一 component，幾分鐘</li><li>去年（Claude 4）：debug 整套檔案，約一小時，重度人工引導</li><li>今年（Fable 5）：整夜運行，跨 agent 團隊，處理整個 linear backlog</li><li>不久的將來：整個 M&amp;A pipeline 端到端自主完成</li></ul><p>開發者痛點（發布前調查）：</p><ul><li>Context management：何時放入何種 context 難以調校</li><li>基礎設施：bursy workload、不可預測計算模式、難以安全擴展</li><li>觀測性：非確定性模型輸出大量非結構化資料，難以判斷品質</li></ul><p><strong>Claude Managed Agents 核心架構</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent（系統提示 + 模型 + skills + tools）</span></span>
<span class="line"><span>  + Environment（網路允許清單 + 預裝包）</span></span>
<span class="line"><span>  = Session（自動配置 sandbox，掛載憑證）</span></span>
<span class="line"><span>  → Events（agent 動作 + user 輸入）</span></span></code></pre></div><p>Events 類型：</p><ul><li><strong>User events</strong>：你發送給 agent 的引導</li><li><strong>Agent events</strong>：agent 的行動（訊息、工具執行、context compaction、委派給其他 agent）</li><li><strong>Session events</strong>：工作單元的生命週期（狀態轉換、錯誤、成果）</li><li><strong>Span events</strong>：關聯事件的聚合檢視</li></ul><p><strong>Pascal demo</strong>（假想線上雜貨外送服務）：agent 分析訂單資料提供洞見（熱銷商品、訂單高峰時段、復購預測）。在 Claude Console 可即時看到所有 events，debug agent 可進一步優化。</p><p><strong>進階功能</strong>（最新發布）：</p><ul><li><strong>Multi-agent orchestration</strong>：委派給獨立 context window 的子 agent 並行處理</li><li><strong>Outcomes</strong>：給定出口條件或 rubric，Claude 持續迭代直到達標</li><li><strong>Memory</strong>：跨 session 讀寫記憶，不再每次從零開始</li><li><strong>Dreaming</strong>：基於 memory，對學習內容反思並蒸餾為精煉記憶</li><li><strong>Self-hosted Sandboxes</strong>：agent loop 和工具執行在你的基礎設施中，檔案和包不離開你的邊界</li><li><strong>MCP Tunneling</strong>：訪問不想暴露到公開網路的私有 MCP server</li><li><strong>Scheduled Deployments</strong>：設定循環排程自動觸發新 session</li><li><strong>Vault</strong>：opaque 佔位符取代真實 secret token，Claude 使用時看不到實際憑證</li></ul><hr><h3 id="workshop-4-—-claude-code-實際應用-44-29–57-43" tabindex="-1">Workshop 4 — Claude Code 實際應用（44:29–57:43） <a class="header-anchor" href="#workshop-4-—-claude-code-實際應用-44-29–57-43" aria-label="Permalink to &quot;Workshop 4 — Claude Code 實際應用（44:29–57:43）&quot;">​</a></h3><p><strong>使命</strong>：縮短「想法→上線產品」之間的距離，透過工具從模型中引出前沿智能，讓每個 builder 都能用上。</p><p><strong>介面演進</strong>：</p><ul><li>CLI（power user，最大控制和自訂）</li><li>IDE（跟隨所有程式碼變更）</li><li>Claude Code on Desktop（全螢幕 GUI，內建預覽、Sidebar、rich output 渲染；跨所有本地和雲端 session 的統一視圖）</li><li>Agents View in CLI（不離開終端的控制平面）</li><li>iOS / Android（遠端控制，移動辦公）</li></ul><p>VS Code IDE extension 和 Desktop app 都基於 Claude Agent SDK（與很多人正在構建的相同 SDK）。</p><p><strong>新功能</strong>（回應開發者反饋）：</p><ul><li><strong>Code Review</strong>：部署一組 agent 捕捉 PR 中的關鍵 bug，Anthropic 所有內部團隊每天使用</li><li><strong>Mobile</strong>（iOS/Android）：遠端控制，不再需要隨身半開著筆電</li><li><strong>Routines</strong>：配置一次，按排程/webhook/API 呼叫自動觸發 Claude Code 任務</li><li><strong>Claude Security</strong>：隔夜掃描 codebase，標記漏洞（含最關鍵項），一鍵啟動 Claude Code session 修復</li><li><strong>Dynamic Workflows</strong>：在確定性結構下並行跑數十到數百個 agent</li></ul><p><strong>Dynamic Workflows demo</strong>（13 語言本地化）：</p><ul><li>串行方式：每語言 3 分鐘，13 種語言需近 1 小時 + 大量手動 prompting</li><li>並行方式：1 個 prompt → workflow 建立 12 個並行翻譯 agent + 12 個驗證 agent，在 Desktop app 側欄可見全部同步運行</li><li>工作流可保存為 JavaScript 供未來複用</li></ul><p><strong>企業採用</strong>：</p><ul><li><strong>Spotify</strong>：月合並 1,000+ PR，遷移時間縮短 90%（基於 Claude Agent SDK 的背景 agent，讀英文遷移計畫自動開 PR）</li><li><strong>Mercari</strong>（日本 C2C 平台）：整個工程團隊使用 Claude Code，工程產出同比增長 90%</li><li><strong>Anthropic 內部</strong>：工程師平均出貨程式碼量是以往的 8 倍</li></ul><hr><h3 id="workshop-5-—-部署-效能、成本、可靠性-57-43–84-55" tabindex="-1">Workshop 5 — 部署：效能、成本、可靠性（57:43–84:55） <a class="header-anchor" href="#workshop-5-—-部署-效能、成本、可靠性-57-43–84-55" aria-label="Permalink to &quot;Workshop 5 — 部署：效能、成本、可靠性（57:43–84:55）&quot;">​</a></h3><p><strong>Prompt Caching（最重要的單一優化）</strong>：</p><p>長程 agentic 應用有大量工具呼叫和用戶輪次，上下文很長，每次請求都重複發送這些長段。Prompt caching 讓我們預計算共用的上下文部分（KV 值），存在服務器上；下一個請求只需計算前次的小增量。</p><p>好處：</p><ul><li><strong>90% 折扣</strong>（只付 10%）</li><li>更快的回應時間</li><li>快取 token 不計入 rate limit</li></ul><p>目標：cache hit rate ≥ 80%（Perplexity、Cursor、Replit 等已達很高命中率，這是它們能被服務的前提）。</p><p>工具：</p><ol><li><strong>Claude Console cache dashboard</strong>：查看 agent 的 cache hit rate（示範中從 0% → 58%，一個小改動就到位）</li><li><strong>Claude API skill</strong>（Claude Code 預裝）：直接說「improve my cache hit rate」，它會修改 prompt 並加入 cache 控制標頭</li></ol><p><strong>Context Engineering（三招管理上下文）</strong>：</p><p><em>1. Tool Search Tool</em>：</p><p>問題：100+ 個工具全部載入上下文，佔用大量 context，但每次運行可能只用其中 10%。 解法：只載入 1 個工具——Tool Search Tool。模型需要工具時先問它，它從庫存中找到對應工具並載入。 效果：Lovable 減少 10% token 用量，且因模型 context 更乾淨，<strong>智能表現也提升</strong>。</p><p><em>2. Programmatic Tool Calling</em>：</p><p>問題：工具回傳大量資料（100 封 email、完整 HTML 頁面），全部放入 context，但可能只需要一個標頭或一個 div。 解法：讓模型看到資料結構後，即時寫程式碼抽取所需的 5% 資料放入 context，其餘丟棄。 效果：Quora 的 HTML 解析 agent 大幅改善（原本拉完整 HTML 頁面，改為只取所需片段）。</p><p><em>3. Compaction</em>：</p><p>問題：即使做了上述優化，長時間運行的 agent（數小時到數天）仍會耗盡上下文。 解法：開發者設定閾值（如 400K），接近時暫停 agent，用另一個模型摘要整個 transcript（移除已無需的中間工具結果），清空上下文放入緊湊摘要，agent 無縫接著跑。 效果：Hex 早已自建類似機制，改用平台版本後<strong>刪除了 300 行程式碼</strong>。</p><p><em>HeroCorp Demo（綜合展示）</em>：</p><ul><li>CEO dashboard，4 個業務目標，原本用 Opus 4.8 消耗百萬 token 只完成 1 個目標</li><li>啟用 Tool Search Tool + Programmatic Tool Calling + Compaction（設 400K 閾值）後，所有 4 個目標全部完成，用量大幅下降</li><li>細節：Tool Search Tool 先查詢「hero retention metrics」再精確呼叫；Gong 會議轉錄工具回傳全文，programmatic tool calling 只抽取情感分析結果；Compaction 從 9K 清回 10K，並給出清晰的「已收集資料 + 待完成事項」摘要</li></ul><p><strong>Advisor 策略（成本 + 品質兼顧）</strong>：</p><p>原理：就像讓初級工程師能問資深工程師幾個問題，效率大幅提升，資深工程師只付出一點時間成本。 做法：Sonnet/Haiku 做工具呼叫（擅長且便宜），給它一個工具讓它能向 Opus/Fable 諮詢（只在需要深度推理時呼叫）。 效果：HeroCorp demo 中，Sonnet 認為某個都市協議「綠燈/正常」，但 Opus advisor 發現 Gong 轉錄底部埋著「市長想要 Cryo Thing 出席開幕式」的訊息——帳戶團隊漏掉了，Opus 標記為紅色警示，最終讓 CEO 重新排期，成功挽救交易。 節省：用便宜模型處理大部分工作，昂貴模型只在需要差異化推理時介入。</p><p><strong>其他 2026 年新功能</strong>：</p><ul><li><strong>WIF（Workload Identity Federation）</strong>：消除 API key，改用工作負載身分聯合，杜絕 key 洩漏風險</li><li><strong>Model Fallback</strong>：Fable 5 安全分類器擋住請求時，Messages API 自動回退到備援模型清單，提升可靠性</li></ul><blockquote><p>以上只是 2026 年上半年發布的部分功能，而我們才過了半年。</p></blockquote><hr><h2 id="逐字稿-含時間戳" tabindex="-1">逐字稿（含時間戳） <a class="header-anchor" href="#逐字稿-含時間戳" aria-label="Permalink to &quot;逐字稿（含時間戳）&quot;">​</a></h2><p><strong>[00:00 → 00:14]</strong> Hi. Good morning, Tokyo. I&#39;m Diane and I joined Anthropic in 2023. And I&#39;ve been a part of every version of Claude since Claude 2. For those of you who are counting, that&#39;s bringing 21 versions of Claude across Haiku, Sonnet, Opus, and now Fable and Mythos to end users and developers like you.</p><p><strong>[00:31 → 00:38]</strong> Our most recent launch happened just a few hours ago. We released Claude Fable 5 and Claude Mythos 5, the first generation of our fifth model.</p><p><strong>[00:38 → 00:48]</strong> Fable 5 is the most capable model we&#39;ve ever made generally available. It&#39;s based on the same foundations as Mythos 5. These models are already accelerating our work at Anthropic.</p><p><strong>[01:09 → 01:24]</strong> For us, as model intelligence increase, we believe the value of use cases it creates increases exponentially. For example, a genetic coding that many of you are using today is far more valuable than simple autocomplete from just a few years ago. And we are already seeing this with Fable 5.</p><p><strong>[01:44 → 01:59]</strong> Fable 5 performs the highest on SWE-bench Pro. But the benchmark itself undersells the story. The longer and the more complicated and sophisticated the task, the farther the gap between Fable and every other model out there. Two things drive that gap.</p><p><strong>[02:06 → 02:25]</strong> The first, single shot correctness. Give Fable 5 a complex, well-specified problem, and it will nail it on the first pass. Early testers have told us about single prompts that essentially create work that would have taken days or even weeks for a group of teams.</p><p><strong>[02:27 → 02:51]</strong> The second is long horizon autonomy. Fable 5 can run for days on a single goal and stay coherent the entire way. It will remember your specifications even on tasks that span millions of tokens. And it can dispatch sub agents, keep them on track far more dependably and with more cost consciousness in any other model we shipped.</p><p><strong>[02:53 → 03:11]</strong> One more thing. Fable 5 isn&#39;t just good at writing code. It&#39;s even better at reading it. It&#39;s better at troubleshooting outages and better at digging through your repo history to figure out what&#39;s broken, when, and also to proactively surface suggestions for making it better.</p><p><strong>[03:11 → 03:48]</strong> Fable 5 is just as much of a step outside of coding. Start with the work that your organizations and companies actually run on, whether that&#39;s financial analysis, documents, slides, spreadsheets. Fable 5 manages that work end to end. It&#39;ll follow instructions, stay on scope, and what it creates back for you will be professional grade because this is a model that we built for workflows at scale.</p><p><strong>[04:02 → 04:23]</strong> Fable 5&#39;s vision is also the best in the industry. It can read dense, technical images, web applications, plots, diagrams, charts far more accurately than any other version of Claude we&#39;ve shipped before.</p><p><strong>[04:23 → 04:43]</strong> Now, everything I&#39;ve talked about is about the upside of a model of this capability. The intelligence of this magnitude cuts both ways. Two months ago, we launched Project Glasswing and made Mythos Preview available to a small group of partners because its capabilities in cybersecurity were strong enough to be potentially misused.</p><p><strong>[04:44 → 04:56]</strong> Since then, we built a new safeguard system, and that safeguard system allows that same intelligence to be shipped and created and used by everyone with Fable 5.</p><p><strong>[04:57 → 05:16]</strong> This is a little of how it works. When a request first touches cybersecurity, biology, or chemistry topics, Fable will route it to our next most capable model, Opus 4.8. The response is clearly labeled, and you&#39;re charged Opus prices.</p><p><strong>[05:18 → 05:36]</strong> We know this is not perfect yet. Researchers doing legitimate work in these fields will sometimes hit a block and reroute, and we&#39;re continuing to work on that. But that&#39;s a type of trade-off that allows our most capable models to be in everyone&#39;s hands today, as of this morning, instead of months from now.</p><p><strong>[05:42 → 06:18]</strong> Rakuten found that the highest effort levels, Fable 5 reflects, validates its work, and for them, that makes autonomous automated operations possible at scale. Cognition ran Fable 5 against their frontier coding eval, Frontier Bench, and it scored the highest of any model they tested. They highlighted the long horizon reasoning and how it generalizes to unfamiliar tools, complex contexts, right out of the box.</p><p><strong>[06:20 → 06:36]</strong> And Jen Spark told us that Fable 5 came out number one in their evals, winning head-to-head against every version of model they&#39;ve tested. It&#39;s actually the strongest on the hardest tasks, such as UI design and game coding.</p><p><strong>[06:38 → 07:24]</strong> So what about Mythos 5? It&#39;s the same underlying model as Fable 5, but with the cyber and biosafeguards lifted. For Mythos Preview, we showed what this model class can do, and Mythos 5 is a step beyond that. It&#39;s available today for our Glasswing partners as part of Project Glasswing. Later this month, we&#39;ll begin enrolling more researchers from life sciences to access Mythos 5 because those same capabilities that make biology risky are actually the same ones that have the highest impact for real good with AI.</p><p><strong>[07:26 → 07:56]</strong> One metric I like to look at to make sense of all of this change is Time Horizon, which is how long a model can work autonomously before losing coherence on what to do next. With Fable 5, we&#39;ve seen agents that are proactive and know what to do without being told. These agents can be responsible for higher level goals, responsibilities that require judgment, collaboration, and proactive taste.</p><p><strong>[08:04 → 08:26]</strong> For example, instead of asking Claude to write a project update, you can now ask Fable to make sure the project stays on track for the whole week. Instead of asking Claude to produce a financial forecast, you can tell Fable to own, update, iterate, and improve on the forecast to keep it accurate.</p><p><strong>[08:26 → 09:20]</strong> As you&#39;ve seen today, the exponential keeps moving. We need to build for emerging capabilities, not just for today&#39;s current models. We expect future versions of Claude to be more capable than the one that even we are releasing today. And Fable 5 and Mythos 5 are just a glimpse into that future. So as developers, how do you take advantage of all of this change ahead? First, you should design for the next version of Claude, not just the current one. What we&#39;ve seen is that countless times the developers who win are the ones whose architectures, harnesses, and product experiences are ready to absorb this next jump in intelligence.</p><p><strong>[09:20 → 09:52]</strong> Claude is intelligent and resourceful. And as models become more intelligent, they can actually do farther with more basic primitives, such as a file system or sandbox computing environments, and far less with sophisticated or too complex harnesses. As models get more intelligent, you will also need to start making harder evals and product prototypes for experiences that may not work yet. This is how you actually know that the exponential is moving underneath you. When a task or a prototype or a product experience that wasn&#39;t quite always working well starts working, that&#39;s a signal to ship something magical that you couldn&#39;t have done before.</p><p><strong>[10:06 → 10:45]</strong> And finally, as the pace continues to accelerate, the teams who win are the ones that get the most out of Claude with model upgrades and treat them as business opportunities. You should make model upgrades easy. This means things like automated evals, testing processes, and making sure that you stay hands on, testing, pushing, creating new things with new versions of Claude. And this is how you&#39;ll know new capabilities will be enough to deliver new experiences for your customers. We&#39;re seeing the exponential continue, which means that Claude will get smarter and be able to pick up new capabilities at scale.</p><p><strong>[11:07 → 11:20]</strong> And we can&#39;t wait to see what you&#39;ll build next with Fable 5. And now Angela and Caitlin are going to show you a bit of how the Claude platform can make this a reality come to life. Thank you so much.</p><p><strong>[11:29 → 11:58]</strong> Hi, everyone. My name is Theo. I work on our long horizon capabilities, such as long context and memory capabilities in our models. I joined about two years ago, right when Sonnet 3.5 had recently launched.</p><p><strong>[12:05 → 12:33]</strong> At the time, agents were barely a word that people were using. There were just signs of life that the models could even do coding at all. People were still focused on chat completions, autonomy, and agent autonomy was something that was still kind of a new concept. Around this time last year, when I go back to Code with Claude last year, Opus 4 had just launched. Claude Code was not even GA. It was still a pretty nascent thing.</p><p><strong>[12:41 → 12:58]</strong> We didn&#39;t know if it would quite take off. It was still pretty new that models could be used for autonomous coding. And of course now, we have Fable, we have Mythos, and recently had also launched Opus 4.8.</p><p><strong>[13:04 → 13:33]</strong> So, before I go into the talk about the capability curve and how models have improved over time, I want to ask you all to raise your hand if you&#39;ve heard of Claude. Now raise your hand again if you&#39;ve used Claude. And keep that hand raised if you think Claude makes you twice as efficient. Keep that hand raised one more time if you think Claude makes you 10x as efficient.</p><p><strong>[14:08 → 14:31]</strong> We recently released a blog post about recursive self-improvement. Over 80% of code internally at Anthropic is merged by Claude. And so as you can see, as models improve over time, we very much expect that capabilities and the ceiling of those capabilities are only going to get better from here.</p><p><strong>[14:45 → 15:10]</strong> So you can see on this slide that we have a series of models and how they performed on SWE-bench verified. This is a trusted coding eval that we use internally to look at Claude&#39;s coding improvements. This eval is made up of a series of GitHub issues and Claude needs to pass these issues and then run on tests to see whether or not it has successfully passed that issue. And if you look all the way back to Sonnet 3.7, you can see that it scored just a little over 60%.</p><p><strong>[15:12 → 15:45]</strong> With Opus 4.8, it is now scoring 88%. And with Mythos and Fable models, we have seen that this benchmark is actually saturated. This is a pretty insane improvement. From 62% to 88% in just 12 months means that Sonnet 3.7 actually failed three times as often on these tasks. Just think about that for a second.</p><p><strong>[15:52 → 16:17]</strong> And so what I&#39;m about to show you is the same task done 12 months apart by two different models. First we&#39;ll see Sonnet 4 performing on this task. And then we&#39;ll go and look at Opus 4.8 on the exact same task. The task that I&#39;m about to show you is rebuilding Claude.ai, our Claude website in one shot.</p><p><strong>[16:17 → 16:55]</strong> Sonnet 4, as you can see, is writing quite a lot of lines of code. It&#39;s calling a lot of tools. It&#39;s jumping right into it. It&#39;s acting before it&#39;s planning. And when you actually go and run the UI, you can see that it actually doesn&#39;t work. Looks reasonable, but not completely functional.</p><p><strong>[16:57 → 17:36]</strong> I&#39;ll voice over what Opus 4.8 would have done on this instead. Opus 4.8 would have built the exact same UI, but it would have actually had the same colors that we would have had on the Claude.ai website. You would have seen the sidebar. You would have seen the chat interface. You could actually send messages and they would actually respond correctly. And it would plan before acting. And not only would it plan before acting, but that planning before acting would ultimately lead to far fewer tool uses called, far fewer lines of code written.</p><p><strong>[17:32 → 17:47]</strong> So at the end of the day, what you&#39;re seeing is that Opus 4.8 not only does the task more successfully, but faster and cheaper.</p><p><strong>[17:51 → 18:20]</strong> So the first thing that we&#39;ll talk about is this idea of planning before acting. Old models would be like me with IKEA furniture. They would jump right in, not look at the instruction manual, just kind of start building and then kind of fail at doing the thing and realize that they had to go back and actually look at that instruction manual. Now models actually plan first. And what that means is that they&#39;re thinking through what the spec should be before they actually go and execute on it.</p><p><strong>[18:32 → 18:57]</strong> And by doing so, as you saw with Opus 4.8 is that the models are actually more efficient by pre-planning that spec. And as it&#39;s pre-planning that spec, it&#39;s then able to actually catch mistakes. So you might see things like the models saying words like &quot;actually&quot; or &quot;never mind.&quot; But by catching those mistakes, it can actually execute on the plan more efficiently the first time around. And so what this means for you is that you should allow the model to think first before actually doing the task.</p><p><strong>[19:03 → 19:23]</strong> Build your products in a way where that thinking is allowed in the user experience, where you are actually giving the model higher effort and adaptive thinking so that it can then do that planning up front. The second area where we see a lot of intelligence gains is in error recovery and self-correction. What I mean by this is that old models used to do this thing called doom looping.</p><p><strong>[19:29 → 20:05]</strong> Doom looping is the idea that the model would be given a task. It would go and do that task. It might fail on the task. You would tell it, &quot;hey, I think you should have done this other thing.&quot; Or maybe something in the environment gave it feedback that it should have done this other thing. It would say great, let me try it again. And as it tried again, it would just kind of keep running into the exact same solution that it had previously and would not change its approach. Now models are able to actually look at that feedback and react to it. And they will actually try something different and try again.</p><p><strong>[20:12 → 20:36]</strong> And so what this means for you is that you should think about designing your environments in a way where you can actually give that feedback to the model so that it can actually then recover from any errors that it&#39;s hitting along the way. And this also means that instead of doom looping and just wasting tokens, models are actually able to perform the task with fewer tokens overall.</p><p><strong>[20:36 → 21:25]</strong> And finally, models now are improving at running over longer and longer horizons. What this means is that models are actually able to sustain attention and hold coherence up to often a million tokens, sometimes even more. Old models would lose the thread partway through. They might forget the task. You might have heard people say that sometimes they see models &quot;losing the plot.&quot; But now we&#39;re seeing that this has improved significantly more. Of course, there&#39;s still room to improve here as we get better at longer context lengths. But now you can actually allow the model to run up to a full million tokens. What that means for you is that you don&#39;t have to do as much context management.</p><p><strong>[21:35 → 22:22]</strong> So I&#39;d recommend as you think about models going for longer and longer horizons that you actually just dream more ambitiously and give it much longer tasks where you can hand it an entire code base and not just a single file. And what this means is that models now can plan a lot better. They run into fewer failures as a result. But when they do run into those failures, they&#39;re able to recover more quickly. And finally, they can just run for longer and longer horizons. And so all of this compounds into these agents that are able to run a lot more autonomously.</p><p><strong>[22:26 → 23:01]</strong> So what this might look like is something like the chart you see here. Where agents first plan, after they plan, they then execute on that plan. You might give them some way to verify against that executed plan. So maybe, again, this is human feedback in a conversation or this is some tool that the agent can call to verify their outputs. They then use that verification to then adjust the plan. And they kind of go back and loop on this again until finally they are happy with the final result.</p><p><strong>[23:01 → 23:42]</strong> But don&#39;t just take this from me, take this from some of our users as well. Here we have a quote from Shopify who has seen that Claude Opus 4.8 is noticeably better — error recovery, planning before acting. Cursor has seen that tool calling and token efficiency in our models is much improved, and that Opus 4.8 is better than every other Opus model that they&#39;ve tested. And similarly, Cognition has also seen that Opus 4.8 is much more autonomous, can run for much longer horizons, and similarly, is also more token efficient.</p><p><strong>[23:54 → 24:19]</strong> So this is the part where everyone is probably most interested in, which is tactically, how do you actually now build for this future? How do you build for the models that are getting better and better over time? This is not just about Opus 4.8 or Opus 4.7 or any of the models that we have today. This is really about helping you guys understand as models improve, what should you be thinking about as a developer so that you can actually give your users those intelligence gains that we&#39;re seeing in the models.</p><p><strong>[24:19 → 24:55]</strong> The first thing before we even get into the tactics is a mindset shift. Be ambitious with what you try and what you allow Claude to handle. Don&#39;t keep testing the same tasks that you think Claude could have done 12 months ago. Start to think about tasks that Claude can&#39;t do today, and think about how you continue thinking about tasks that Claude can&#39;t do today, because as models improve, more and more of those tasks are going to be possible, and you want to be able to see as those tasks become possible.</p><p><strong>[24:55 → 26:07]</strong> And the first way that you do this is by building evals. Refreshing your evals, if you already have evals. But oftentimes this is the first step for people to even understand what is possible in models today. So if you don&#39;t have evals, the way to think about this is that they are unit tests for the AI era. Some of these can be regression tests based where these are all tests that the models today can already do, and you&#39;re just looking to see whether or not your harness or future models are able to do the same things. But often what you actually want to do is create evals that today&#39;s models do not saturate.</p><p><strong>[26:07 → 26:55]</strong> Secondly, update your evals that might be saturated. So we sometimes hear from customers when we launch new models that they&#39;ll say something like, &quot;hey, on my eval, it only really improved by 1%. I don&#39;t think this model is that much better.&quot; And over time, as they start to play around with the model more and more, they realize, &quot;oh, actually, this model is significantly better on a couple of capabilities or maybe this one axis that my eval just didn&#39;t test for at all.&quot; And so this is a testament that if you&#39;re seeing that your eval is not moving very much, you may want to look at whether or not the remaining problems that are not yet solved by models in that eval are actually fair and solvable.</p><p><strong>[27:02 → 27:21]</strong> And finally, once you do have that eval, the best thing that you can do is just benchmark it so that you understand how various models are performing on it and as new models come out to actually then look at how those new models are performing on it.</p><p><strong>[27:11 → 28:13]</strong> Secondly, and I can&#39;t say this enough, shrink your scaffolding. Scaffolding is the prompts around the model, the tools that you might be using around the models, any code that you have. Sometimes people also call this the harness. But as you look at your harness and your scaffold, oftentimes people are adding new things to it over time because of various failure modes that maybe prior models ran into. And so an example here is that we at one point had a line in our Claude.ai system prompt that specified a specific citation format that was now out of date. And our new models got significantly better at instruction following and started following that instruction in the system prompt that we had put in there a while ago. And so we thought that citations were broken in this new model until we looked at the system prompt and realized that actually the model had just gotten better at instruction following and what we really needed to do was to just remove that line entirely from the system prompt.</p><p><strong>[28:19 → 28:48]</strong> This is an example where shrinking the scaffolding and just letting the model have a little bit more autonomy actually helps you to see what that model can do in practice. And so what you want to do is write your prompts for intent and what you want the model to ultimately do and not just to write those prompts around all of the past failures that you may have run into with prior models.</p><p><strong>[28:48 → 29:27]</strong> And finally, you want to give the model room to work. You want to use adaptive thinking which gives the model the ability to decide when it needs to think and how much it needs to think. And there&#39;s also an effort dial that you can use to actually dial up or down how hard the model works on problems. Secondly, you want to allow your agents to have more access to your environment to take more actions but do so in a controlled way. So as we talked about, models are becoming more and more autonomous, they&#39;re becoming more intelligent.</p><p><strong>[29:33 → 30:12]</strong> And one way that we do this internally is that we launched auto mode in Claude Code which is a classifier that tells Claude what actions are safe to take. Of course, you don&#39;t want to just allow your model to kind of run wild and maybe delete everything in its environment. So you do want to be a little bit controlled with what it has access to. But doing it in this kind of classifier way allows us to kind of strike the right balance of how much control we want to take but also how much control we want to give the model. And finally, you want to close the agent loop. Models are now very good at error recovery but it needs to know when it has made an error. And so the way that you tell the model whether or not it&#39;s made an error is by giving it a way to verify its outputs.</p><p><strong>[30:28 → 30:52]</strong> For example, maybe if you&#39;re building an application building agent, you might want to give it a computer use tool. And with that computer use tool, it can then QA the front end. It can click around. It can see if it actually works. And that way, it can then get that feedback from its environment to understand if you should then go and update the code. So with that, thank you so much for listening to my talk on the capability curve.</p><p><strong>[30:52 → 31:27]</strong> Welcome to Code with Claude, everyone. I&#39;m Jess, product for Claude Managed Agents. And I&#39;m Michael, engineering for Claude Managed Agents. It has been so exciting to see the organic uptake on Claude Managed Agents and how we&#39;re accelerating meaningfully developer workflows. This is a story that we want to share with you today.</p><p><strong>[31:41 → 32:08]</strong> We&#39;ve seen uptake from disruptive startups all the way to the largest enterprises. And we want to make sure that you can all benefit from the kind of experiences that they&#39;ve had as well. So first, we&#39;ll go over the exponential that we&#39;ve seen in AI capabilities and what that implies for building agents. We&#39;ll talk through the patterns we saw in agent development and why that motivated us to build Claude Managed Agents.</p><p><strong>[32:20 → 32:35]</strong> As we&#39;ve all seen, models are getting exponentially more capable. And so are our expectations. The more advanced our model capabilities, the more sophisticated the work that we&#39;re delegating. We&#39;re now seeing that the bottleneck is increasingly the infrastructure and not actually the intelligence.</p><p><strong>[32:37 → 33:40]</strong> So let&#39;s bring this to life. Two years ago, when Opus 3 was announced, you might have it write and test a single component. It would take minutes of focused work. Last year, when our Claude 4 models came out, we leveled up and you could debug an entire set of files. You might be working for an hour or so, but you&#39;d be steering heavily along the way. With our latest models this year, you&#39;re now seeing them run overnight. Across agent teams, listening to your linear backlog and actually the whole thing before you wake up. And now we suspect that in the near term future, with models as capable as Fable, we&#39;ll enter a world where agents are capable enough to accomplish tasks that would have previously taken entire teams of people quarters to achieve. And agents will run this entirely autonomously.</p><p><strong>[33:33 → 34:14]</strong> So you might see that multi-agent systems could coordinate and run an entire M&amp;A pipeline end to end in a fraction of the time it would take us. And so as tasks have graduated from low-level instructions towards end-to-end outcome description, we now need far more than just prompts and tool loop, we need reliable and scalable agentic infrastructure. And the more complex these tasks, the deeper the access we&#39;ll need to give these agents in order for them to be effective. With models like Fable, you can&#39;t run an effective agent without granting it access to your credentials, your internal knowledge bases, or your databases.</p><p><strong>[34:18 → 34:47]</strong> If you want these agents to produce code for you, you need to give them access to your actual code bases so that they can push up PRs and go to production. And finally, you need to grant them identity and authentication. Our agents are increasingly acting not just as Claude but as me or Jess, with our emails and our Slack. And as we grant agents these human-like capabilities, we expect to interact with them in much more human-like ways.</p><p><strong>[34:41 → 35:25]</strong> The shape of interactions are changing, not just the duration of these interactions. Some agents are very conversational. You steer, provide guidance along the way, you might even interrupt it if you think that it is going off-path. Some agents on new models like Fable are really outcome-oriented. And if you have strong signal or a rubric of what you want to see get done, you can provide it that rubric and let it iterate until your exit criteria are met. And then finally, you might start a task a couple days ago and then want to pick it up much, much later. A robust agent platform needs to support all these sorts of interaction patterns.</p><p><strong>[35:27 → 36:04]</strong> So it&#39;s now becoming clear that we expect a lot of our agents. And historically, this has meant that we&#39;ve pushed the burden on to you, the developer. In research we conducted prior to launching Claude Managed Agents, we saw that developers were genuinely eager to climb the exponential with us, but were struggling with a few key areas. First, context management — the right context at the right time is actually really difficult to tune. Second, infrastructure concerns are their number one production blocker — agents create bursty workloads, unpredictable compute patterns, it&#39;s super difficult to scale securely while also hitting latency targets. And lastly, observability is genuinely incredibly difficult.</p><p><strong>[36:26 → 36:55]</strong> And so enter Claude Managed Agents. We did the platform work so that you don&#39;t have to. Managed agents combines infrastructure, agentic primitives, and out of the box observability, all available in a package on the Claude platform.</p><p><strong>[36:51 → 37:35]</strong> So let&#39;s talk about the very basic building blocks of Claude Managed Agents. At the very, very core, you have an agent that you define. This would be the system prompt, the model you want to use, any skills that you might want to have loaded into your agent, and tools with permissions for those tools that you want that agent to have. This is like the agent&#39;s identity. Next you have the environment that you configure — a template where you define a network allow list and any pre-install packages. This is like the world that the agent is going to live in. You take that, the environment, and the agent, and you use that to run a session. A sandbox is provisioned for you. We set up the harness, and Claude starts executing.</p><p><strong>[37:35 → 38:06]</strong> Any credentials and resources that you might want to include in that session are mounted into it and are available for Claude to use. Finally, we have events. These are anything that the agent produces as it&#39;s doing actions, or any events that you might want to provide upstream in order to steer the agent. This is how you might want to stay in the loop. Events and stateful awareness is really where we&#39;re able to provide a platform so that you can build your own products on top of.</p><p><strong>[38:07 → 38:55]</strong> Everything in managed agents is event-based. These are durable transcripts that are clearly structured to help you track your agent&#39;s progress. First, there are user events — actually what you&#39;re sending to the agent to guide it. Next, there are agent events — what the agent is actually doing (messaging, tool execution, context compaction, and even delegation to other agents). Next, there are session events — how you understand the progress of the unit of work you&#39;ve just delegated (overall life cycle, status transitions, errors, and outcome process). And lastly, there are span events — groups related events in a more aggregated, instrumented way.</p><p><strong>[39:01 → 39:41]</strong> So let&#39;s pivot to a real world example of something that we built using Claude Managed Agents, which is Pascal, which uses a hypothetical online grocery delivery service&#39;s order data in order to analyze that data and provide insights for our team. The agent produces analytics in minutes, leveraging a preloaded data set and a set of Python packages and scripts that we installed and uploaded into the container that it works from. You can see every event in Claude console and even chat with a debug agent in order to further optimize your integration.</p><p><strong>[41:01 → 41:52]</strong> So now that we have covered the basics, I want to touch on some of the more advanced features that we recently shipped. First, multi-agent orchestration — Claude is able to delegate tasks to other agents with independent context windows, enabling it to parallelize increasingly complex work. With outcomes, Claude iterates on predefined exit criteria or a rubric until it satisfies its goal. You&#39;re in charge of this goal and Claude is in charge of completing it. With memory, Claude is able to read and write to memory stores. By default, without memory, Claude would be starting fresh on every session. But with memory, it has an awareness of prior runs and can do better this next time. Dreaming is built on top of memory — Claude is reflecting and codifying on learnings into new memories.</p><p><strong>[42:54 → 43:39]</strong> All of these are really exciting intelligence features, and we&#39;re really excited to raise the ceiling of what agents can produce. However, we also have heard that we need to meet you where you are. And that means making our infrastructure more modular. So with self-hosted sandboxes, you can run the agent loop and have tool execution directly in your infrastructure, so files and packages never leave your perimeter. With MCP tunneling, Claude can access private MCP servers that you would not want to expose to the open internet. Each of these things are built so that you can deploy within your enterprise, within your own security principles.</p><p><strong>[43:42 → 44:12]</strong> And in addition to all these amazing features that we already have, we just released two new very exciting features. One is scheduled deployments, which allow you to set up a recurring schedule which will trigger new sessions on your behalf for any recurring work that you might have. And then next we have environment variables inside Vaults, which allow you to provide secure credentials for any APIs or CLIs that you might want Claude to call without actually having any sort of risk about Claude seeing the actual secret tokens.</p><p><strong>[44:13 → 44:35]</strong> Diving a little bit deeper into how environment variables work in Vaults: we place an opaque placeholder token inside the container itself that Claude has access to. And whenever Claude is trying to hit an API or use a CLI, it will just use that environment variable the way that it would use any other environment variable.</p><p><strong>[44:41 → 45:06]</strong> With Claude Code, we&#39;re bringing that same leverage to your work as a developer — not agents you ship to customers, but agents that ship code for you. First, I want to thank all the developers in the room today here and watching online. Thank you for trusting Claude Code back when Sonnet 3.7 was our frontier model and when our product was rough around the edges. Your support is what makes the team so excited to come in every day and make the product even better.</p><p><strong>[45:20 → 45:55]</strong> Let&#39;s back up to why Claude Code exists. The mission of Claude Code is to bridge the difference between an idea and a shipped product. The way that we enable this is we build tools that elicit the frontier intelligence from our models and we make these tools accessible to every builder. And we don&#39;t think of ourselves as having a finished roadmap to share with you. We think of ourselves more like mountaineers climbing alongside you in terrain that none of us has fully mapped yet, figuring out what works together as we go.</p><p><strong>[46:01 → 46:31]</strong> I remember just last year, I would give Claude Code a task and I would review every single edit that it made, giving it detailed instructions about what it should do instead, walking through on every little detail of these simple tasks. Now, many of us are using auto mode to delegate permissions to Claude and only checking in after Claude Code has already tested its changes and put up a PR that&#39;s ready for our review.</p><p><strong>[46:31 → 47:15]</strong> Claude Code started in the CLI. And this is still the place for power users who want a minimal text interface and the most control and customizations. Then we added the IDE for users who want the same powerful agents but want to follow along with all of the code changes. Then we heard from many of you that you&#39;re running multiple Claude Codes in parallel, which you&#39;ve affectionately called &quot;multi-Claudes.&quot; And we&#39;ve added two new interfaces to help make that easier.</p><p><strong>[47:15 → 47:55]</strong> The one that I use most frequently is Claude Code on Claude Desktop. It&#39;s designed for people who want this full screen graphical interface with built-in previews, a sidebar control plane, and the ability to render images and rich outputs. We built desktop to be a single view across all your local and cloud sessions with visual indicators of which agents are working and which ones need your input.</p><p><strong>[47:49 → 48:18]</strong> Next is our newest surface, Claude Agents View in the CLI. For those of you who want a control plane without having to ever leave the terminal, you can see what&#39;s waiting on you, what&#39;s running, and what&#39;s already done. You can reply in line to unblock or jump in and out of any session without losing your place. The VS code IDE extension and the Claude Code on Claude Desktop app are built on the Claude Agent SDK, the same one that many of you are building on today.</p><p><strong>[48:21 → 48:58]</strong> Many enterprises have now adopted these Claude Code tools wall to wall. At Anthropic, engineers on average ship 8x more code than they did in past years, even as the size of our engineering team has grown substantially. Together with you all, we&#39;re excited to discover and redefine what the future of engineering looks like by embracing new challenges that come and by building automations powered by Claude to attack each one.</p><p><strong>[48:58 → 49:36]</strong> Here&#39;s some of the feedback that we&#39;ve heard from our users and the products that we&#39;ve built to address each one with the help of folks in this community. We heard from you that you want to spend less time on code review. So we shipped a code review product that deploys a team of agents to catch critical bugs in your PRs. Thousands of companies use this every day and this includes all internal Anthropic teams. We heard from you that you really want to code on the go. So we launched remote control and Claude Code on iOS and Android.</p><p><strong>[49:48 → 50:16]</strong> And we heard from you that you want to run Claude Code on new tickets. And so we built routines. You can configure this once and it will run on a schedule, a web hook, or an API call to kick off Claude Code on the right task. So the work that used to require a human to manually kick off routines can take care of for you.</p><p><strong>[50:16 → 50:50]</strong> And we heard from you that you&#39;re landing so much code that your security teams are having a hard time keeping up. So we built Claude Security. It scans your code base overnight. It flags a range of vulnerabilities including the ones that it believes are most critical and lets you kick off a Claude Code session to tackle each one.</p><p><strong>[50:43 → 51:14]</strong> And then finally, we heard that you want better ways to run ambitious large scale tasks across your code base, like major refactors and migrations. So we launched dynamic workflows. This lets you kick off Claude Code to run in parallel across tens or hundreds of agents in a deterministic structure to get your most ambitious tasks done.</p><p><strong>[51:20 → 52:14]</strong> For instance, Spotify uses Claude to migrate thousands of repos. The team built a background agent on the Claude Agent SDK that reads a migration plan in plain English and then kicks off a fleet of agents that opens PRs. They&#39;re merging over a thousand PRs a month into production and they&#39;ve cut migration time down by 90%. Another example is Mercari, Japan&#39;s consumer-to-consumer marketplace. At Mercari, the entire engineering team runs on Claude Code and they&#39;ve measured that engineering output is up 90% year over year using the tool.</p><p><strong>[52:21 → 52:58]</strong> We see this across the industry. Millions of developers are getting more done and at higher quality than before. Now, let&#39;s see what this actually looks like in practice. I&#39;m excited to show you one of my favorite new features in Claude Code. For this demo, let&#39;s imagine we&#39;re Kaizen Operations and we create apps for engineering teams. Right now, our marketing website is in English only, but we want to launch the 13 additional markets, so we need to localize our site before the launch.</p><p><strong>[52:51 → 53:35]</strong> Let&#39;s start with how we would normally do this with one Claude Code agent. We&#39;ll run this prompt asking Claude to convert our website to Japanese and we&#39;ll speed things up as it works. Claude explores the code base, creates a language picker for the website and translates all the text to Japanese. So, Claude finished his work and let&#39;s check out the results. We can see a full marketing site and view the new Japanese translation from Claude. It took Claude about three minutes to complete this one translation and we have 12 more to go.</p><p><strong>[53:35 → 54:17]</strong> If we did this one at a time sequentially, it would take us almost an hour and lots of manual prompting with Claude. So, instead, we&#39;ll use a dynamic workflow which will let Claude create a repeatable process and run each of the new translations at the same time in parallel. We&#39;ll prompt Claude to use a workflow for our translation to these 12 new languages. Claude creates a workflow and once it&#39;s ready, we can open it in the side pane and watch as it works. This is a powerful feature of the Claude Desktop app. You can see all 12 translation agents running at the same time.</p><p><strong>[54:17 → 54:52]</strong> After the translation agents complete, it&#39;s going to create 12 more agents to verify its work across these new languages. This work would have previously required us to run 12 separate tasks and it can now be done in just one prompt. And we can also save this workflow as JavaScript code and reuse it for future translations. Claude has now created 12 new versions of the website all localized with one action.</p><p><strong>[55:00 → 55:14]</strong> We can use them for large scale migrations, code-base audits, or doing performance optimizations. Any large job that requires running many agents at once in a deterministic structure.</p><p><strong>[55:15 → 55:49]</strong> Everything you just saw is available today including dynamic workflows and Claude Code in the Claude Desktop app. And our newest model, Claude Fable 5, is available to all Claude Code users so you can use the latest intelligence wherever you use Claude Code. We&#39;re so excited for you to try out these new features and for you to let us know what you think. We hope they continue to help you close the gap between an idea and a shipped product.</p><p><strong>[55:49 → 56:36]</strong> And this is really what every talk today was pointing at. Diane&#39;s capability curve, Angela&#39;s agents that run on infrastructure that you control, and what I just showed you. These are three layers to one story. The remaining gap is just how fast we can put these great capabilities to work for us. I encourage you to spend the rest of today exploring these layers. Join research talks if you want to learn more about the latest model capabilities. Join Claude platform sessions if you&#39;re building your own agents for your end users. Or join Claude Code workshops if you want to learn more ways to bring Claude Code into your day-to-day development work.</p><p><strong>[57:48 → 58:10]</strong> Good afternoon. Thank you for coming. You&#39;ve almost made it to the end of Code with Claude. And this session is going to be well worth your effort. Because in this session we&#39;re going to talk about not just building agents but how you deploy agents that are secure, reliable, performant, and most importantly cost effective. So you can actually do that at scale.</p><p><strong>[58:18 → 58:53]</strong> I know many of you have started building agents already. A few of you maybe have agents in production but only a very few are really happy with the performance, reliability, and cost effectiveness of their agents. So this talk is really going to drill into that.</p><p><strong>[58:53 → 59:47]</strong> So let&#39;s drill in. And first before we talk about any of the other techniques and tools that we&#39;ll cover today I want to talk about prompt caching. This is the single most important takeaway of the talk. You see in long running agentic applications there are many tool calls, many user turns, and the transcripts get very long. And each request to the API then repeats these long segments of prompt. And if we have to recompute those segments every single time it&#39;s expensive and slow. So we offer prompt caching which lets us pre-compute the shared part of the context. We store those in an intermediate value, we call those KV values, but we store those pre-computed parts of the prompt up on our servers.</p><p><strong>[59:47 → 60:16]</strong> And then the next request that comes in we just have to do the small delta from the previous request. And that saves a lot of compute. And we pass that savings on to you. So the most important benefit of prompt caching — it&#39;s at a 90% discount. So you pay only 10% of the cost when you use prompt caching. In addition you get faster response times and your rate limits aren&#39;t affected by prompt caching. For any tokens that are cached we don&#39;t count against that for rate limits in the API.</p><p><strong>[60:22 → 61:27]</strong> And we&#39;ve got some customers that have done a very good job in prompt caching. If you look at Perplexity, Cursor, Replit, all of these customers have spent significant engineering effort to bring their cache hit rate up very high. In fact if these customers didn&#39;t have such a high cache hit rate we couldn&#39;t even serve their workload because there&#39;s just not enough compute without prompt caching. So it&#39;s very important. But the good news for you is you can get similarly high cache hit rates with much less amount of effort. One — if you go into our developer console or our Claude console you can see this new dashboard that reports on your cache hit rate. The agent I&#39;m showing here has only a 56% cache hit rate so it&#39;s got some room for improvement. I invite you to as soon as you get home go and check out what your agent&#39;s cache hit rate is. If it&#39;s not up in the 80s then I would suggest that&#39;s the first thing to go work on.</p><p><strong>[61:39 → 62:17]</strong> The second big tip I&#39;ll give you to get your cache hit rate up is to use our Claude API skill. It&#39;s a new skill. It&#39;s installed by default with Claude Code. But it knows very well how to do prompt caching. So if you just go into Claude Code open your project up and say &quot;improve my cache hit rate&quot; it will start working with you to modify the prompt add the cache control headers and whatnot in order to get your cache hit rate up high.</p><p><strong>[62:28 → 63:11]</strong> So what we&#39;re building here is a dashboard for a CEO. A CEO has a set of objectives and we&#39;ve written an agent that goes out and... wait a second Rod, is this the right UI? Well we&#39;re Code with Claude Tokyo and you bring this like 90s looking SharePoint UI. I don&#39;t know. I think we can do better. Rod has Claude Code on that machine. Rod, see if you can give us a better theme. Let&#39;s think about what might be more appropriate for this audience in Tokyo. Yeah that&#39;s exactly right. We need to keep this exciting. So Rod&#39;s going to make a superhero theme demo.</p><p><strong>[63:38 → 64:19]</strong> Much better! Okay so we&#39;re no longer the CEO of some boring corporation. This is now the dashboard for the CEO of HeroCorp and what HeroCorp does is it rents out superheroes to defend your city, to defeat villains, and to show up at kids&#39; birthday parties whatever is necessary. We have a set of objectives and we&#39;re reporting on the status of those objectives by scouring all the data that this corporation has.</p><p><strong>[64:38 → 65:18]</strong> Rod is invested in prompt caching and wait — Rod, it&#39;s a zero percent cache hit rate. We talked about doing — I gave the whole thing on prompt caching being so important — zero percent. Okay right, maybe you can implement prompt caching real quick. So Rod&#39;s going to go into Claude Code and implement prompt caching for us. With one little change we got up to 58% cache hit rate. I invite you to look at this over the course of the demo as we add more functionality to it you&#39;ll see that cache hit rate goes up even further.</p><p><strong>[65:46 → 66:24]</strong> We got to objective one, let&#39;s scroll down — we didn&#39;t even load objective two. It says we&#39;ve run out of context and we didn&#39;t even get to objective two. You can see the context window indicator here Rod, it gave you a million token context and we only got to one of the four objectives with a million tokens. I think we can do better. You know what I think we need — we need a little context engineering.</p><p><strong>[66:24 → 67:00]</strong> Okay context engineering is the discipline of deciding what belongs in Claude&#39;s context and it really is an engineering technique. You want enough in Claude&#39;s context for Claude to make good reasoned decisions but you don&#39;t want so much that&#39;s distracting and expensive and slow. Today I&#39;m going to talk about three different tools that you have in order to be able to manage the context in agents that you build.</p><p><strong>[67:00 → 67:27]</strong> The first is Tool Search Tool and that&#39;s going to keep a bunch of tool definitions out of your context. The second is programmatic tool calling and that&#39;s going to keep a bunch of the tool results out of your context. And then finally I&#39;ll talk about compaction.</p><p><strong>[67:27 → 68:20]</strong> So with Tool Search Tool, the key problem it solves is that many agents have 10, 20, 100 tools in order to do their jobs and we want agents to have a lot of tools. What&#39;s problematic is having 100 plus tools in the context because if you have 100 tools you&#39;re going to consume most of your context with just tool definitions, leaving only a little bit for the actual running of the agents. And that&#39;s not very wise because most of the trajectories, most of the runs of your agent, may only use 10% of those tools yet you&#39;ve loaded them all into context. You paid for that in terms of cost, you paid for it in terms of latency.</p><p><strong>[68:27 → 69:09]</strong> So Tool Search Tool — what we&#39;ve done is we just loaded one tool, the Tool Search Tool. And then when the model decides it needs a tool it first asks the Tool Search Tool &quot;do you have a tool for this?&quot; And then the Tool Search Tool searches over its inventory of tools and picks the right one for that query and loads that into context. And so consequently you get much more agentic space — you&#39;re able to use the context much more efficiently because you only load exactly the tools you need for any given run.</p><p><strong>[69:09 → 69:54]</strong> And customers like Lovable have really seen some benefits from this — just with this change alone they reduced their token usage by 10%. But not only that, actually much more important to Lovable was that the performance, the intelligence was better for everybody. Because when the model gets so much into context sometimes the judgment isn&#39;t quite as good. And so by reducing what goes into context the model itself performed better.</p><p><strong>[69:54 → 70:14]</strong> Okay, that&#39;s Tool Search Tool. Let&#39;s switch and talk about programmatic tool calling. With programmatic tool calling the goal here is to get the intermediate tool results out of the context. You see, many tools — you actually want to design the tools so that they return lots of data because you want the model to have whatever context it might need.</p><p><strong>[70:21 → 71:17]</strong> But if you have a tool like the Outlook tool we saw earlier and it returns 100 emails — well that&#39;s going to eat up a lot of your context when maybe you only needed the header of one of the emails. Or if you have an HTML page maybe you only needed a small div tag out of it but you loaded all of that in the context. So what we did to solve this is actually just lean on the fact that our models are actually very good at writing code. So rather than just using a tool call, what we do is we do the tool call, we get the full results out of the tool call, and then the model is able to inspect that schema and then write code against the schema of whatever that arbitrary block of data is. So in real time it can write code and pull out just the bits of information — say five percent, two percent of that data — and put that result into context.</p><p><strong>[71:46 → 72:13]</strong> And customers like Quora have seen big benefits from this. For Quora&#39;s agent they do a lot of HTML — they pull a lot of HTML in and they were pulling full HTML pages in when they only needed just a little bit of the page. And when they moved to this it really helped their agent perform so much better.</p><p><strong>[72:13 → 73:35]</strong> Okay, that&#39;s programmatic tool calling. Next up is compaction. So even if you do a great job on Tool Search Tool and programmatic tool calling you may still run out of context because they do still have context. So if you have an agent that is very ambitious, that needs to run for hours or even days, then you want to do something like compaction. And what compaction does is it lets you as the developer set a threshold — you can say I want to use only 400 or 500K of my one million token context window. And then when the context gets up to that point, close to that threshold, what we&#39;ll do is we&#39;ll pause execution of the agent, we take another model, have it summarize the entire transcript, strip out all the things that are just not needed anymore — all these intermediate tool results and tool calls that aren&#39;t needed because the decision that needed them was already made. Then we clear all of that out and put a small tight summary of what happened so far and restart the agent. It just picks up exactly where it left off.</p><p><strong>[73:47 → 74:06]</strong> And we saw companies like Hex pick this up. Turns out Hex had already implemented a version of this, so they were able to remove 300 lines of code and just not have that maintenance burden. Much better to have us have the maintenance burden than you.</p><p><strong>[74:11 → 74:53]</strong> So let&#39;s switch back to the demo. When last we left HeroCorp, remember we consumed a million token of context with just one of our four objectives. So we want to see if we can actually make this load using all of these strategies. Rod, let&#39;s go into Claude Code and enable Tool Search Tool, programmatic tool calling and compaction all in one go — get all these strategies configured. Okay so we have all these going now. If we switch over and reload, notice a lot more things are happening now. You see the context window is going up, the activity stream shows lots of tool calls because we&#39;re filling in every one of those objectives. And we ended up with a much smaller context.</p><p><strong>[75:26 → 76:08]</strong> So let&#39;s walk through these one at a time. Starting with Tool Search Tool at the very top: the first thing that happened was the model decided to call the Tool Search Tool and it looked for &quot;hero retention metrics.&quot; Tool Search Tool said &quot;oh, I have a tool like that — here&#39;s the schema for it&quot; and it&#39;s called hero_retention_metrics with underscores. Then the model actually called that tool and got its result. So we didn&#39;t have to load all those hundred-plus tools up front, we could just load one at a time.</p><p><strong>[76:16 → 77:02]</strong> Next up we have programmatic tool calling. We have this Gong customer digest — Gong is a meeting transcription tool, so it returns the entire transcription of a meeting. That&#39;s nice to have but really we only wanted the sentiment of this meeting. So rather than the whole transcript, you can see that it actually wrote code using code executor, with calls to all of those methods, and then it pulls the JSON out and prints only a little bit of the JSON — only the smallest piece that we actually needed for this run to happen. And that saves a lot of context.</p><p><strong>[77:10 → 77:32]</strong> And then finally, compaction — you can see here it fired, we dropped 9K, brought it back down to 10K, and then you can see the summary that was done. We&#39;re being clear with the model that&#39;s picking this up: &quot;here&#39;s the objective, here&#39;s the data we already gathered, here&#39;s what you need to do next.&quot; So it&#39;s a really tight summary.</p><p><strong>[78:11 → 78:27]</strong> One thing though — nobody has really commented on this but I mean, I&#39;m not from Japan, but I think 1,600 yen is a lot for one request. Is that a lot of money? That&#39;s a lot of money for one request. I think we can do better. So let&#39;s switch back to slides and talk about how we can optimize that a little bit.</p><p><strong>[78:29 → 79:07]</strong> So the way we&#39;re going to optimize this is to talk about the Advisor strategy. Really the insight from Advisor strategy is not going to be new to you if you&#39;ve ever worked with a development team. You know that you can make a junior engineer on your team more productive just by giving them access to a senior engineer. If you just let a senior engineer review their code, let the junior engineer ask the senior engineer a couple of questions every day, that junior engineer will get way better and it will cost the senior engineer just a little bit. The same thing is true with models.</p><p><strong>[79:07 → 79:31]</strong> You can take a small inexpensive model and make it way better by giving it a tool to let it talk to a bigger model. So if you have a model like Sonnet or Haiku you can make those models way smarter by giving them an advisor that&#39;s Opus or Fable. And I know I heard some murmurings about the cost of Fable being 2x what Opus is — this is a great way you can get some of the reasoning capabilities of Fable for a fraction of the cost.</p><p><strong>[79:49 → 80:11]</strong> It turns out Haiku and Sonnet are so good at writing code, they&#39;re so good at doing tool calling. The thing they&#39;re not as good at is really deep insight and reasoning. So why not let Haiku and Sonnet do what they&#39;re good at for less money and then only use models like Opus and Fable where you really need that differentiated reasoning. And we see customers like Bolt doing that.</p><p><strong>[80:16 → 81:11]</strong> So let&#39;s switch back over to the demo. You can see we&#39;re in the debug view, the model we&#39;re using right now is Opus 4.8. If you go into Claude Code we&#39;ll switch on advisor mode. We could just change it to Sonnet and that would be cheaper, right? But the problem is this is a dashboard for our CEO making business decisions — we can&#39;t afford to be wrong. So we need to be inexpensive and we need to be right — both are important. Now we switched it and now Sonnet is calling all these tools.</p><p><strong>[81:18 → 82:06]</strong> What happened is Sonnet is calling the advisor periodically. In this particular example that Rod found for us, Sonnet called the advisor running Opus, and Opus actually disagreed with the decision that Sonnet had made. Sonnet had said &quot;yeah, this Metropolis deal — green check, it&#39;s on track.&quot; Opus looked over the transcripts and actually caught a problem — said &quot;oh Sonnet, you missed this one case.&quot; Turns out buried at the bottom of a Gong transcript, the mayor of Metropolis said he really wanted Cryo Thing to come to the opening, and that got missed by the account team. So it&#39;s actually red.</p><p><strong>[82:16 → 82:35]</strong> So if we look at the deal, you see that it&#39;s red. And that&#39;s thanks to the Opus Advisor. So we didn&#39;t just save money — we save money, that&#39;s great, but we also kept this level of higher level reasoning. And so if we go ahead and click that, boom — the CEO has now rescheduled Cryo Thing, and we&#39;re going to close this deal.</p><p><strong>[82:44 → 83:10]</strong> So I think what Rod was able to show us in this demo is with Advisor, we can use more inexpensive models and use more expensive models only where they&#39;re needed. Three different context engineering techniques, and prompt caching. So thanks a lot, Rod, I appreciate it.</p><p><strong>[83:04 → 83:34]</strong> Okay, let&#39;s just wrap up. We talked about prompt caching — you should be at 80% if you&#39;re building an agent, so definitely check that out. We talked about Tool Search Tool, where you can keep that from filling up your context. Programmatic tool calling to keep the tool results out. And then compaction. And finally we talked about Advisor, where you can use more inexpensive models and get the same level of reasoning.</p><p><strong>[83:34 → 84:14]</strong> But the Claude platform is evolving very fast, and it&#39;s a great way to stay up on the latest capabilities. This is just what we launched in 2026. Just in the interest of time, I&#39;ll just call out a couple. I&#39;m a real big fan of the workload identity federation or WIF. What WIF does is it removes the need for an API key. I know a lot of customers maybe check in API keys into source code, leave them lying around. They could be a leak risk. If somebody gets your API key, they can query on your behalf. With WIF, that&#39;s eliminated.</p><p><strong>[84:14 → 84:52]</strong> And the other thing I&#39;ll mention is just today, we launched the Fable model. And it&#39;s a Mythos class model, so we had to put additional safety classifiers on it. And that means the block rate&#39;s a little bit higher on that model than on other models. And so we launched a fallback feature. So now on the Messages API, you can just list a few other models. You can say, &quot;oh, if Fable can&#39;t handle it for whatever reason, because of classifier fires, then the request will just automatically fall back.&quot; And that makes it have a more reliable, robust experience.</p><p><strong>[84:52 → 84:55]</strong> So that&#39;s just two of all the many things that we&#39;ve launched. And we&#39;re only halfway through the year.</p><hr><h2 id="完整純文字" tabindex="-1">完整純文字 <a class="header-anchor" href="#完整純文字" aria-label="Permalink to &quot;完整純文字&quot;">​</a></h2><p>Hi. Good morning, Tokyo. I&#39;m Diane and I joined Anthropic in 2023. And I&#39;ve been a part of every version of Claude since Claude 2. For those of you who are counting, that&#39;s bringing 21 versions of Claude across Haiku, Sonnet, Opus, and now Fable and Mythos to end users and developers like you. Our most recent launch happened just a few hours ago. We released Claude Fable 5 and Claude Mythos 5, the first generation of our fifth model. Fable 5 is the most capable model we&#39;ve ever made generally available. It&#39;s based on the same foundations as Mythos 5. These models are already accelerating our work at Anthropic. And for developers like you, Claude will be able to be stronger and your starting line will move forward. We talk a lot about the exponential at Anthropic. But what does this actually mean? For us, as model intelligence increase, we believe the value of use cases it creates increases exponentially. For example, agentic coding that many of you are using today is far more valuable than simple autocomplete from just a few years ago. And we are already seeing this with Fable 5.</p><p>Let&#39;s start with coding, because we believe that&#39;s where most of you will feel the magic first. Fable 5 performs the highest on SWE-bench Pro. But the benchmark itself undersells the story. The longer and the more complicated and sophisticated the task, the farther the gap between Fable and every other model out there. Two things drive that gap. The first, single shot correctness. Give Fable 5 a complex, well-specified problem, and it will nail it on the first pass. Early testers have told us about single prompts that essentially create work that would have taken days or even weeks for a group of teams. The second is long horizon autonomy. Fable 5 can run for days on a single goal and stay coherent the entire way. It will remember your specifications even on tasks that span millions of tokens. And it can dispatch sub agents, keep them on track far more dependably and with more cost consciousness in any other model we shipped.</p><p>One more thing. Fable 5 isn&#39;t just good at writing code. It&#39;s even better at reading it. It&#39;s better at troubleshooting outages and better at digging through your repo history to figure out what&#39;s broken, when, and also to proactively surface suggestions for making it better. Fable 5 is just as much of a step outside of coding. Start with the work that your organizations and companies actually run on, whether that&#39;s financial analysis, documents, slides, spreadsheets. Fable 5 manages that work end to end. It&#39;ll follow instructions, stay on scope, and what it creates back for you will be professional grade because this is a model that we built for workflows at scale. It&#39;s also better where requests aren&#39;t clean. When you give Fable 5 something messy, multi-threaded, and ask it to figure out what to do next, it can do that work and outshine other versions of Claude.</p><p>Fable 5&#39;s vision is also the best in the industry. It can read dense, technical images, web applications, plots, diagrams, charts far more accurately than any other version of Claude we&#39;ve shipped before. Now, everything I&#39;ve talked about is about the upside of a model of this capability. The intelligence of this magnitude cuts both ways. Two months ago, we launched Project Glasswing and made Mythos Preview available to a small group of partners because its capabilities in cybersecurity were strong enough to be potentially misused. Since then, we built a new safeguard system, and that safeguard system allows that same intelligence to be shipped and created and used by everyone with Fable 5. This is a little of how it works. When a request first touches cybersecurity, biology, or chemistry topics, Fable will route it to our next most capable model, Opus 4.8. The response is clearly labeled, and you&#39;re charged Opus prices. We know this is not perfect yet. Researchers doing legitimate work in these fields will sometimes hit a block and reroute, and we&#39;re continuing to work on that. But that&#39;s a type of trade-off that allows our most capable models to be in everyone&#39;s hands today, as of this morning, instead of months from now.</p><p>So what about Mythos 5? It&#39;s the same underlying model as Fable 5, but with the cyber and biosafeguards lifted. It&#39;s available today for our Glasswing partners. Later this month, we&#39;ll begin enrolling more researchers from life sciences. As developers, the key metrics and recommendations: design for the next version of Claude, make harder evals, make model upgrades easy. These are the teams that win.</p><p>My name is Theo. I work on long horizon capabilities. I joined about two years ago right when Sonnet 3.5 had recently launched. At the time, agents were barely a word that people were using. There were just signs of life that the models could even do coding at all. Around this time last year, Opus 4 had just launched, Claude Code was not even GA. Now we have Fable, Mythos, and recently launched Opus 4.8.</p><p>Over 80% of code internally at Anthropic is merged by Claude. On SWE-bench verified: Sonnet 3.7 scored just over 60%. With Opus 4.8, it is now scoring 88%. And with Mythos and Fable models, we have seen that this benchmark is actually saturated. From 62% to 88% in just 12 months means that Sonnet 3.7 actually failed three times as often on these tasks. The same task done 12 months apart: Sonnet 4 acts before it plans and the UI doesn&#39;t work. Opus 4.8 plans first, executes more efficiently, with fewer tool uses and less code, and the result is correct.</p><p>Three areas of intelligence gains: First, planning before acting — models now think through the spec before executing, catching mistakes mid-plan. This means fewer iterations and higher first-pass success. Second, error recovery and self-correction — old models doom-looped (kept hitting the same failed solution). Now models actually look at feedback and try something different. Third, long horizon coherence — models can sustain attention and hold coherence up to a million tokens or more. Old models would &quot;lose the plot.&quot; Now you can hand it an entire codebase and not just a single file.</p><p>Tactical advice: Be ambitious — test tasks Claude can&#39;t do today. Build evals (they are unit tests for the AI era; create tests that today&#39;s models don&#39;t saturate). Shrink scaffolding (write prompts for intent, not for past failures; an outdated citation format line in the system prompt can break new models). Give the model room (adaptive thinking, effort dial, more environment access via controlled classifier, close the agent loop with verification tools like computer use).</p><p>Welcome to Code with Claude, everyone. I&#39;m Jess, product for Claude Managed Agents. And I&#39;m Michael, engineering for Claude Managed Agents. Models are getting exponentially more capable — and so are our expectations. The bottleneck is increasingly the infrastructure, not the intelligence. Two years ago (Opus 3): single component, minutes. Last year (Claude 4): entire file sets, one hour, heavy steering. This year (Fable 5): overnight, cross-agent teams, entire backlogs. Near future: entire M&amp;A pipeline end-to-end, entirely autonomously.</p><p>Developer pain points: context management, infrastructure scaling, observability. Claude Managed Agents solves all of this: agent config + environment + sessions + events. Events are durable transcripts (user events, agent events, session events, span events). Pascal demo shows grocery analytics agent running in minutes with full event visibility in Claude Console.</p><p>Advanced features: multi-agent orchestration (parallel independent context windows), outcomes (iterate to rubric), memory (cross-session awareness), dreaming (reflect and codify learnings), self-hosted sandboxes, MCP tunneling, scheduled deployments, Vault (opaque env vars for secret credentials).</p><p>With Claude Code, we&#39;re bringing that same leverage to your work as a developer — not agents you ship to customers, but agents that ship code for you. The mission of Claude Code is to bridge the difference between an idea and a shipped product. Claude Code started in the CLI, then IDE, then Desktop (full-screen GUI, sidebar, rich outputs, unified view across all sessions), then CLI Agents View, then iOS/Android.</p><p>New products: Code Review (team of agents catches critical bugs in PRs, all Anthropic teams use it daily), Mobile (iOS/Android remote control), Routines (configure once, runs on schedule/webhook/API), Claude Security (overnight vulnerability scanning), Dynamic Workflows (parallel agents in deterministic structure for large-scale tasks).</p><p>Enterprise: Spotify merging 1,000+ PRs/month, 90% migration time reduction. Mercari 90% engineering output increase year over year. Anthropic internal: engineers ship 8x more code. Dynamic Workflows demo: sequential 13-language localization ~1 hour → parallel with 1 prompt, 12 translation agents + 12 verification agents running simultaneously, saveable as JavaScript for reuse.</p><p>Good afternoon. This session covers deploying agents that are secure, reliable, performant, and cost effective at scale. The single most important takeaway: prompt caching. Long-running agentic apps have many tool calls, long transcripts, repeated long prompt segments. Prompt caching pre-computes shared context as KV values on our servers. Each new request only computes the small delta. Benefit: 90% discount (pay only 10%), faster responses, cached tokens don&#39;t count against rate limits. Target: ≥80% cache hit rate. Tools: Claude Console cache dashboard, Claude API skill in Claude Code.</p><p>Context engineering — deciding what belongs in Claude&#39;s context. Three techniques: Tool Search Tool (load only the tools needed for each run — Lovable: 10% token savings + better intelligence), Programmatic Tool Calling (model writes code to extract only needed data from tool results — Quora: dramatically improved HTML parsing), Compaction (set threshold like 400K, automatically summarize and clear context when reached — Hex: removed 300 lines of self-built implementation).</p><p>HeroCorp demo: with all three enabled, all four CEO objectives completed instead of just one, with much smaller context. Tool Search Tool: loaded hero_retention_metrics on demand. Programmatic tool calling: extracted only meeting sentiment from full Gong transcript. Compaction: dropped 9K, restarted cleanly with tight summary.</p><p>Advisor strategy: Sonnet/Haiku for tool calling (cheap and good at it), Opus/Fable as advisor (only for deep reasoning). Like giving a junior engineer access to a senior engineer. HeroCorp demo: Sonnet marked Metropolis deal green; Opus advisor caught buried Cryo Thing issue and flagged red — CEO rescheduled, deal saved. Cost optimized while maintaining accuracy.</p><p>Other 2026 features: WIF (workload identity federation — no API keys needed, eliminates leak risk), Model Fallback (if Fable classifier fires, automatically falls back to listed backup models for reliability). And we&#39;re only halfway through the year.</p><hr><h2 id="核心摘要" tabindex="-1">核心摘要 <a class="header-anchor" href="#核心摘要" aria-label="Permalink to &quot;核心摘要&quot;">​</a></h2><blockquote><p>Anthropic 在東京 Code with Claude 大會同日發布 Claude Fable 5 與 Mythos 5（第五代模型），並辦 5 場工作坊揭示能力、基礎設施與部署最佳實踐。</p></blockquote><hr><h3 id="workshop-1-fable-5-能力-diane" tabindex="-1">Workshop 1：Fable 5 能力（Diane） <a class="header-anchor" href="#workshop-1-fable-5-能力-diane" aria-label="Permalink to &quot;Workshop 1：Fable 5 能力（Diane）&quot;">​</a></h3><p><strong>核心升級</strong>：</p><ul><li><strong>單次正確率</strong>：複雜任務一次通過，早期測試者稱單個 prompt 可完成原本需要一個團隊花數天/週的工作</li><li><strong>長程自主性</strong>：單一目標可運行數天，跨百萬 token 保持連貫，sub-agent 調度更可靠且有成本意識</li><li><strong>視覺理解</strong>：讀取技術圖表、UI 截圖、圖表的準確度創新高</li><li><strong>安全機制</strong>：網路安全/生物/化學請求自動路由 Opus 4.8，回應標注、收 Opus 定價</li></ul><p><strong>Mythos 5</strong>：解除安全限制版，今日對 Glasswing 合作夥伴開放；本月擴及生命科學研究者。</p><p><strong>開發建議</strong>：為下一版 Claude 設計架構、建立測試今日不可行體驗的 eval、讓 model 升級變成商業機會。</p><hr><h3 id="workshop-2-能力曲線-theo" tabindex="-1">Workshop 2：能力曲線（Theo） <a class="header-anchor" href="#workshop-2-能力曲線-theo" aria-label="Permalink to &quot;Workshop 2：能力曲線（Theo）&quot;">​</a></h3><p><strong>SWE-bench 進展</strong>：Sonnet 3.7 → Opus 4.8 = 62% → 88%（Fable/Mythos 已飽和此 benchmark）；12 個月內舊模型失敗率是新模型 3 倍。</p><p><strong>三大智能躍升</strong>：</p><ol><li><strong>先規劃後執行</strong>：不再盲衝，先思考規格再執行，途中自我修正，首次成功率大幅提升</li><li><strong>錯誤恢復</strong>：終結 doom-looping，真正看懂反饋並嘗試不同方法，token 消耗更少</li><li><strong>長程連貫</strong>：支撐至百萬 token 不失焦，可接手整個 codebase 而非單一檔案</li></ol><p><strong>戰術三點</strong>：</p><ol><li><strong>建立野心型 eval</strong>：測試今天做不到的事，飽和的 eval 要更新</li><li><strong>縮短 scaffolding</strong>：提示寫意圖而非修補舊失敗，過時指令反而誤導新模型</li><li><strong>給模型空間</strong>：adaptive thinking + effort dial；用 classifier 控制的 environment 訪問；閉合 agent loop（給驗證工具）</li></ol><hr><h3 id="workshop-3-claude-managed-agents-jess-michael" tabindex="-1">Workshop 3：Claude Managed Agents（Jess + Michael） <a class="header-anchor" href="#workshop-3-claude-managed-agents-jess-michael" aria-label="Permalink to &quot;Workshop 3：Claude Managed Agents（Jess + Michael）&quot;">​</a></h3><p><strong>托管基礎設施三層</strong>：</p><ul><li><strong>代理基礎設施</strong>：Agent（定義）+ Environment（網路+包）→ Session（sandbox 自動配置）+ Events（durably-recorded transcript）</li><li><strong>代理原語</strong>：Multi-agent 協調、Outcomes/Rubrics（出口條件迭代）、Memory（跨 session）、Dreaming（反思蒸餾記憶）</li><li><strong>觀測性</strong>：event-based transcript，Claude Console 即時監控，debug agent 優化整合</li></ul><p><strong>最新功能</strong>：</p><ul><li>Scheduled Deployments（排程觸發 session）</li><li>Vault（opaque 環境變數，模型看不到真實 secret）</li><li>Self-hosted Sandboxes（tool 執行在自有基礎設施）</li><li>MCP Tunneling（私有 MCP 存取）</li></ul><hr><h3 id="workshop-4-claude-code-應用-claude-code-團隊" tabindex="-1">Workshop 4：Claude Code 應用（Claude Code 團隊） <a class="header-anchor" href="#workshop-4-claude-code-應用-claude-code-團隊" aria-label="Permalink to &quot;Workshop 4：Claude Code 應用（Claude Code 團隊）&quot;">​</a></h3><p><strong>使命</strong>：縮短「想法→上線」的差距。</p><p><strong>介面全覆蓋</strong>：CLI → IDE → Desktop（全螢幕 + sidebar + rich output）→ Agents View → iOS/Android</p><p><strong>新功能</strong>：</p><ul><li><strong>Dynamic Workflows</strong>：確定性結構下並行數十到數百 agent；13 語言本地化 demo：串行 ~1h → 並行 1 prompt；可保存為 JavaScript 複用</li><li><strong>Code Review</strong>：批次 bug 捕捉，Anthropic 全內部使用</li><li><strong>Routines</strong>：排程/Webhook/API 觸發</li><li><strong>Claude Security</strong>：隔夜安全掃描</li></ul><p><strong>企業採用</strong>：</p><ul><li>Spotify：1,000+ PR/月，遷移時間 -90%</li><li>Mercari：工程產出 +90% YoY</li><li>Anthropic 內部：工程師出貨程式碼量 8x</li></ul><hr><h3 id="workshop-5-部署最佳實踐-部署工程師-rod-demo" tabindex="-1">Workshop 5：部署最佳實踐（部署工程師 + Rod demo） <a class="header-anchor" href="#workshop-5-部署最佳實踐-部署工程師-rod-demo" aria-label="Permalink to &quot;Workshop 5：部署最佳實踐（部署工程師 + Rod demo）&quot;">​</a></h3><p><strong>Prompt Caching（最重要）</strong>：</p><ul><li>90% 折扣、不占 rate limit</li><li>目標：cache hit rate ≥ 80%</li><li>工具：Claude Console 儀表板 + Claude API skill（說「improve my cache hit rate」）</li></ul><p><strong>Context Engineering 三招</strong>：</p><table tabindex="0"><thead><tr><th>技術</th><th>解決問題</th><th>效果</th></tr></thead><tbody><tr><td><strong>Tool Search Tool</strong></td><td>100+ 工具佔滿 context</td><td>Lovable: token -10% + 智能↑</td></tr><tr><td><strong>Programmatic Tool Calling</strong></td><td>工具回傳大量資料只需少量</td><td>Quora: HTML agent 大幅改善</td></tr><tr><td><strong>Compaction</strong>（閾值如 400K）</td><td>長程 agent 耗盡 context</td><td>Hex: 刪除 300 行自建程式碼</td></tr></tbody></table><p><strong>Advisor 策略</strong>：</p><ul><li>Sonnet/Haiku 做工具呼叫（便宜且擅長）</li><li>Opus/Fable 只在需要深度推理時介入</li><li>HeroCorp demo：Opus advisor 抓住 Sonnet 漏掉的合約關鍵細節，以更低成本維持高品質推理</li></ul><p><strong>其他新功能</strong>：</p><ul><li><strong>WIF</strong>：工作負載身分聯合，消除 API key 洩漏風險</li><li><strong>Model Fallback</strong>：Fable 分類器擋請求時自動降回備援模型</li></ul><blockquote><p>以上只是 2026 年上半年發布的功能——而我們才過了半年。</p></blockquote>`,272)])])}const p=t(s,[["render",i]]);export{g as __pageData,p as default};
